// DensePlan is the simulation this process runs, from LLM_DENSE_SIM plus the
// two scope variables. It is read once, and a bad spec is fatal rather than
// ignored: a run that silently measured the wrong bank would be worse than
// one that did not start.
//
//	LLM_DENSE_SIM=q4_0/32                        every streamed dense family
//	LLM_DENSE_SIM=deltanet=q4_0/32,lm_head=q5sym/32   a width per family
//	LLM_DENSE_SIM_FAMILIES=deltanet,lm_head      restrict a single-width spec
//	LLM_DENSE_SIM_SRC=tail                       only what the checkpoint
//	                                             does not ship as Q8_0
func DensePlan() QuantPlan {
	denseSimOnce.Do(func() {
		p, err := ParseQuantPlan(os.Getenv("LLM_DENSE_SIM"),
			os.Getenv("LLM_DENSE_SIM_FAMILIES"), os.Getenv("LLM_DENSE_SIM_SRC"),
			os.Getenv("LLM_DENSE_SIM_QUANT"))
		if err != nil {
			panic(err)
		}
		densePlan = p
	})
	return densePlan
}

var (
	denseBankOnce sync.Once
	denseBankPlan QuantPlan
)

// DenseBankPlan is which dense families are staged on **the real 4.5-bit
// bank** (bank_q4.go), from `LLM_DENSE_BANK` — the same grammar `LLM_DENSE_SIM`
// takes, and `LLM_DENSE_BANK_QUANT` beside it, because a plan is a plan
// whether it is simulated or built.
//
//	LLM_DENSE_BANK=lm_head=q4_k/32              the family L8c-4 has a kernel for
//	LLM_DENSE_BANK_QUANT=imatrix                the default; rtn is the control
//
// It defaults to `imatrix` where `LLM_DENSE_SIM` defaults to `rtn`, and that
// is deliberate: a simulation's default arm is the one every L8c-1 rung was
// measured with, where a *bank*'s is the one L8c-3 recommends building
// (+4.24% against the calibrated symmetric form's +15.63%). A family the
// matrix does not cover falls back to round-to-nearest the way ggml does.
//
// The two are separate variables and a run that sets both is measuring
// something incoherent — a weight quantised twice — so `-ppl` and the graph
// refuse it rather than average it.
func DenseBankPlan() QuantPlan {
	denseBankOnce.Do(func() {
		mode := os.Getenv("LLM_DENSE_BANK_QUANT")
		if strings.TrimSpace(mode) == "" {
			mode = "imatrix"
		}
		p, err := ParseQuantPlan(os.Getenv("LLM_DENSE_BANK"), "", "", mode)
		if err != nil {
			panic(err)
		}
		if !p.Off() && !DensePlan().Off() {
			panic(fmt.Errorf("llm: LLM_DENSE_BANK=%s and LLM_DENSE_SIM=%s would quantise the same weight twice",
				p, DensePlan()))
		}
		denseBankPlan = p
	})
	return denseBankPlan
}

// ApplyTo round-trips one staged weight through the plan, if the plan covers
// it, and records what it touched.
//
// It is the single entry point both staging paths use — `Model.F32` for
// everything and `gpu_head.go` for the lm head, which is too big to reach the
// device as floats — because the two behaving differently is exactly the bug
// L8c-1 found. x is [n][k] row-major, which is ggml's own order for a weight
// stated [k, n].
func (p QuantPlan) ApplyTo(name string, q8Source bool, x []float32, k int) error {
	q, ok := p.For(name, q8Source)
	if !ok {
		return nil
	}
	var qw []float32
	if q.Mode == "imatrix" {
		im, err := DefaultImatrix()
		if err != nil {
			return err
		}
		if qw, err = im.Columns(name); err != nil {
			return fmt.Errorf("%s: %w", name, err)
		}
		if qw == nil {
			// **The published matrix has no entry for this tensor**, which
			// is not a failure and is not rare: unsloth's covers `blk.N.*`
			// only, so `output.weight` and the head mixer's two projections
			// — 0.636 B weights, 14% of a dense token — have no calibration
			// data at all.
			//
			// ggml does exactly this: `quantize_row_q4_0_impl` returns
			// `quantize_row_q4_0_ref` when `quant_weights` is null, so an
			// uncovered tensor is round-to-nearest. Following it keeps the
			// simulation's arms comparable to a real `llama-quantize`, and
			// the tally below is what stops that being invisible — a plan
			// that is half calibrated has to say so.
			q.Mode = "rtn"
			simCountUncal(name, len(x))
		}
	}
	if err := q.ApplyWeighted(x, k, qw); err != nil {
		return fmt.Errorf("%s: %w", name, err)
	}
	simCount(name, len(x))
	return nil
}

// imatrixCols is the published importance row for a tensor, or nil — which is
// both "this mode does not calibrate" and "the matrix has no entry for this
// tensor", because ggml treats the second as the first
// (`quantize_row_q4_K_impl` falls back to `_ref` on a null `quant_weights`)
// and so does everything here.
//
// It is `ApplyTo`'s lookup as a function, because L8c-4's *bank* needs the
// same row the *simulation* used and the two reading different matrices would
// be the bug this file was written to avoid.
func imatrixCols(name, mode string) ([]float32, error) {
	if mode != "imatrix" && mode != "imatrix+gain" {
		return nil, nil
	}
	im, err := DefaultImatrix()
	if err != nil {
		return nil, err
	}
	qw, err := im.Columns(name)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", name, err)
	}
	return qw, nil
}

// The simulation's own tally, by family.
//
// It exists because of the bug it would have caught. `lm_head` screened as
// **exactly** unchanged at 4 bits — 0.636 B parameters re-quantised and not
// one logit moved — because the head is the one dense weight that does not

	if v >= 0 {
		return float32(int32(v + 0.5))
	}
	return float32(int32(v - 0.5))
}

// simFamily names the streamed dense family a tensor belongs to, or "" if the
// simulation must not touch it.
//
// The list is the answer to "what does D3 mean by everything *streamed*", and
// it is a whitelist rather than a filter because the cost of being wrong is
// asymmetric: re-quantising a norm weight or the router's ties would produce
// a perplexity that is not the format's, and nothing downstream would say so.
//
// Out of scope by construction, and each for its own reason:
//
//   - **the 512 expert banks** never pass through Model.F32 at all — L5b
//     stages them byte for byte out of the mmap'd checkpoint, so they keep
//     the checkpoint's Q4_K/Q5_K/Q5_1/Q8_0 whatever this is set to, and D4
//     says not to go below them anyway;
//   - **`token_embd` and the n-gram table** are gathers, not matmuls (D2);
//   - **every norm, `ssm_a`, `ssm_dt.bias` and `ssm_conv1d`** are elementwise
//     parameters, 1-D or nearly, and are not read a row at a time;
//   - **`ffn_gate_inp`, the router** is F32 in the checkpoint and D3 keeps it
//     at fp16: it is 0.25 GB a token and its ties decide which ten of 512
//     experts run (L5a).
func simFamily(name string) string {
	base := name
	if i := strings.Index(name, "."); i >= 0 && strings.HasPrefix(name, "blk.") {
		if j := strings.Index(name[i+1:], "."); j >= 0 {
			base = name[i+1+j+1:]
		}
	}
	switch base {
	case "hc_attn_down.weight", "hc_attn_up.weight", "hc_attn_inject.weight",
		"hc_ffn_down.weight", "hc_ffn_up.weight", "hc_ffn_inject.weight":
		return "hyper_conn"
	case "attn_q.weight", "attn_k.weight", "attn_v.weight":
		return "full_attn"
	case "attn_output.weight":
		return "full_attn"
	case "indexer.q_proj.weight", "indexer.k_proj.weight":
		return "qsa_indexer"
	case "attn_qkv.weight", "attn_gate.weight", "ssm_out.weight":
		return "deltanet"
	case "ssm_alpha.weight", "ssm_beta.weight":
		return "deltanet"
	}
	switch base {
	case "ple_key.weight", "ple_value.weight":
		// L2d's fused key/value projection. It runs once, at layer 1, for
		// 0.6% of a decode step — small enough that LLM.md wrote it down
		// rather than narrowing it at L8b, and cheap enough to price here
		// rather than leave as the one streamed matmul nobody measured.
		return "ple_proj"
	}
	switch name {
	case "output.weight":
		return "lm_head"
	case "output_hc_down.weight", "output_hc_up.weight":
		return "hyper_conn"
	}
	return ""
}

	return attnVariant{}, false
}

// GEMMKernel names one build of the plain arm of llm_gemm.comp, by its row
// block. Both of this layer's projections read a B far larger than the MALL —
// the fused QKV weight is 71.4 MB and the output projection 31.5 — so the rung
// is chosen against the weight, exactly as the PLE block's is: a workgroup
// carrying BM token rows reads all of B M/BM times.
type GEMMKernel string

const (
	GEMMM2 GEMMKernel = "gemm_m2"
	GEMMM4 GEMMKernel = "gemm_m4"
	GEMMM8 GEMMKernel = "gemm_m8"
)

type gemmVariant struct {
	name  GEMMKernel
	spirv []byte
	bm    int
}

var gemmVariants = []gemmVariant{
	{GEMMM2, shaders.LLMGEMMPlainM2, 32},
	{GEMMM4, shaders.LLMGEMMPlainM4, 64},
	{GEMMM8, shaders.LLMGEMMPlainM8, 128},
}

// The same three rungs over L8's dense bank: int8 tiles and an fp16 scale
// plane instead of halves, unpacked into LDS per K-step. They are a separate
// table rather than a field on the one above because a *build* of the kernel
// is what differs, and the two are never mixed inside one block — a bank is
// staged one way or the other and the rung is chosen afterwards.
var gemmQ8Variants = []gemmVariant{
	{GEMMM2, shaders.LLMGEMMQ8M2, 32},
	{GEMMM4, shaders.LLMGEMMQ8M4, 64},
	{GEMMM8, shaders.LLMGEMMQ8M8, 128},
}

// The same three rungs again over L8c-4's 4.5-bit bank: nibble tiles and a
// sixteen-byte ggml record per (column, super-block).
var gemmQ4Variants = []gemmVariant{
	{GEMMM2, shaders.LLMGEMMQ4M2, 32},
	{GEMMM4, shaders.LLMGEMMQ4M4, 64},
	{GEMMM8, shaders.LLMGEMMQ4M8, 128},
}

// gemmBuildsFor is the table a block builds its pipelines from, by bank.
func gemmBuildsFor(b DenseBank) []gemmVariant {
	switch b {
	case BankQ8:
		return gemmQ8Variants
	case BankQ4K:
		return gemmQ4Variants
	}
	return gemmVariants
}

// GEMMKernels lists the rungs, narrowest first.
func GEMMKernels() []GEMMKernel { return []GEMMKernel{GEMMM2, GEMMM4, GEMMM8} }

// GEMMKernelFor is the rung for the *fused projection*, whose B is 71.4 MB —
// 2.2x the MALL — so it is chosen against the weight exactly as L2d's is: a
// workgroup carrying BM token rows reads all of B M/BM times, and that is the
// whole shape of this dispatch. Measured, us per layer, BM 32 / 64 / 128:
//
//	T =   64    497 /  413 /  452      64 rows do not fill a BM of 128
//	T =  128    917 /  529 /  452
//	T =  512   3118 / 2003 / 1520
//	T = 2048  19060 / 9570 / 6027      a 3.2x spread on identical arithmetic
func GEMMKernelFor(tokens int) GEMMKernel {
	if tokens <= 64 {
		return GEMMM4
	}
	return GEMMM8
}

// OutGEMMKernelFor is the rung for the *output projection*, and it is a
// different one at every length — which is the point of having two.
//
// Its B is 31.5 MB, just **inside** the 32 MiB MALL where the fused
// projection's is 2.2x past it, and the two ladders separate on exactly that.
// Measured, us per layer, BM 32 / 64 / 128:
//
//	T =   64    138 /  170 /  286      the widest rung is 2.1x the narrowest
//	T =  128    194 /  205 /  285
//	T =  256    265 /  306 /  316
//	T =  512    507 /  458 /  519      the middle rung, and only here
//	T = 1024   1035 /  965 /  858
//	T = 2048   2142 / 1807 / 1623      now the widest, 1.32x the narrowest
//
// So the schedule inverts across the sweep: at 64 tokens BM=128 is the worst
// rung by 2.1x and at 2048 it is the best by 1.32x, on the same kernel and the
// same arithmetic. While B fits the MALL, reading it fewer times buys nothing
// and the occupancy a narrow row block leaves is the whole story; once M is
// large enough that the *activation* traffic dominates, the wide rung wins
// back. The fused projection never has the first regime because its B never
// fits, which is why one schedule could not serve both.
func OutGEMMKernelFor(tokens int) GEMMKernel {
	switch {
	case tokens <= 256:
		return GEMMM2
	case tokens <= 512:
		return GEMMM4
	default:
		return GEMMM8
	}
}

func gemmVariantFor(k GEMMKernel) (gemmVariant, bool) {
	for _, v := range gemmVariants {
		if v.name == k {
			return v, true
		}
	}
	return gemmVariant{}, false
}

// attnLayerWeights is where one layer's staged weights sit.
type attnLayerWeights struct {

package llm

// The dense bank at 4.5 bits: LLM.md L8c-4.
//
// L8a and L8b staged every dense weight in the width the checkpoint already
// ships — int8 with an fp16 scale per 32 — which is bit-identical arithmetic
// and took a decode token from 9.67 GB to 6.05. That is where the
// *checkpoint's* width runs out. L8c then measured what a narrower one costs,
// and the answer turned twice: symmetric Q4 at 4.5 bits is +18.5% of
// perplexity, and ggml's **asymmetric** K-quant at the same 4.500 bits is
// +7.04% uncalibrated and **+4.24% with unsloth's published imatrix**
// (L8c-3). So this is the bank that measurement recommends: 4.264 GB a token
// against 6.334 and a 56.7 tok/s ceiling against 38.2.
//
// # The layout
//
// Everything about it is §2.8's fragment tiling with a *nibble* where L8a
// puts a byte, plus a second plane that is ggml's own super-block record.
//
//	tiles    tile (nt, kt) is 128 contiguous bytes, kt fastest inside an
//	         n-tile, holding element (k, n) of the matrix at nibble
//	         (n%16)*16 + k%16 — byte (n%16)*8 + (k%16)/2, low nibble for
//	         even k. So a `uint` is eight consecutive k of one output
//	         column, where L8a's is four.
//
//	records  one per (n-tile, super-block, row): `d` and `dmin` as halves
//	         and then the 6-bit (scale, min) pair of every group, which is
//	         **sixteen bytes at eight groups** — ggml's own
//	         `get_scale_min_k4` record — and **twenty at ten** (see below).
//	         Indexed ((nt*nsb + sb)*16 + n%16), so the sixteen records a
//	         tile column needs are one contiguous run — the same k-major
//	         arrangement D8 chose for L8a's scale plane, for the same
//	         reason.
//
// 4 bits of level, 12 bits a group of 32 and 32 bits a super-block of 256 is
// **4.500 bits a weight**, which is the number every L8c-3 rung is quoted at.
//
// # The 320-wide family, and the one place this is not ggml
//
// A super-block is ggml's eight groups wherever `k % 256 == 0`, which is
// every dense matrix in this model but one family. `hc_{attn,ffn}_up` and
// `output_hc_up` read the low-rank space and are 320 wide, so their
// super-block is the **whole row** — ten groups — exactly as the simulation
// L8c-3 measured them with (`asymSubBlocks`). What does not carry over is the
// record: `get_scale_min_k4` is four low pairs and four high ones and it is
// not a length, so a ten-group record uses `packScaleMin12` instead and is
// twenty bytes rather than sixteen. The levels, the scales and the mins are
// the simulation's to the bit; only where the bits sit differs.

import (
	"fmt"
	"sync"
)

// q4kSuper is the groups in a super-block: ggml's QK_K/32.
const q4kSuper = 8

// q4kRecord is one super-block's parameters for one row: d, dmin and the
// twelve packed 6-bit pairs.
const q4kRecord = 16

// q4kShape is a row's division into super-blocks and the record size that
// division implies: eight groups into sixteen bytes, or ten into twenty.
func q4kShape(k int) (sub, nsb, rec int, err error) {
	if sub, err = asymSubBlocks(k, 32); err != nil {
		return 0, 0, 0, err
	}
	if err = q4kPackFits(sub); err != nil {
		return 0, 0, 0, err
	}
	return sub, k / (sub * 32), q4kRecordBytes(sub), nil
}

// q4kBytes is the staged size of an [n, k] matrix: the nibble tiles, then the
// record plane. As with L8a's, the kernel derives the plane's offset from
// bOff + n*k/2 rather than from a push field — 64 uints is this device's
// whole push range and the block has been full since L5b.
func q4kBytes(n, k int) int {
	_, nsb, rec, err := q4kShape(k)
	if err != nil {
		return 0
	}
	return n*k/2 + (n/coopMatTile)*nsb*coopMatTile*rec
}

// q4kRecPlane is the record plane's size for an [n, k] matrix, which the two
// planes' callers allocate separately because they write them separately.
func q4kRecPlane(n, k int) int {
	_, nsb, rec, err := q4kShape(k)
	if err != nil {
		return 0
	}
	return (n / coopMatTile) * nsb * coopMatTile * rec
}

// q4kFits reports whether a matrix can be staged in this bank at all.
func q4kFits(n, k int) error {
	if n%coopMatTile != 0 {
		return fmt.Errorf("llm: a q4_k bank wants whole %d-row tiles, not %d rows", coopMatTile, n)
	}
	_, _, _, err := q4kShape(k)
	return err
}

// tileBQ4K writes one [n, k] row-major matrix into the bank, quantising it
// through the same encoder `sim.go` measured the format with.
//
// `src` is n rows of k floats, `row` is tileB's row remapping, `q` the format
// (`q4_k/32`) and `qw` the importance of each of the k input columns
// — the imatrix row for this tensor, or nil for round-to-nearest.
//
// dstQ and dstR are the destination's two planes, and their length is what
// says how many rows the destination has. They are the *whole* matrix's or a
// slab's, as long as the slab is whole sixteen-row tiles of the destination,
// which is what lets the lm head stage 4096 rows at a time without a 2.54 GB
// copy of itself ever existing — and they may be wider than `n`, which is
// what lets four of llama.cpp's matrices be staged into one fused plane.
func tileBQ4K(dstQ, dstR []byte, src []float32, n, k int, row func(int) int, q QuantSim, qw []float32) error {
	sub, nsb, recBytes, err := q4kShape(k)
	if err != nil {
		return err
	}
	// **The destination's rows are the plane's, not the source's.** The lm
	// head stages one matrix into a plane of its own size, but the gated
	// DeltaNet's fused projection is four of llama.cpp's matrices written
	// into one — `row` sends each source row to its column of the fused
	// output — so the plane a call fills is wider than the rows it carries.
	// The buffer says how wide: dstQ is dstN*k/2 bytes and nothing else can
	// be, which is the same check one level up.
	dstN := len(dstQ) * 2 / k
	if err := q4kFits(dstN, k); err != nil {
		return err
	}
	if !q.Asym || q.Group != 32 {
		return fmt.Errorf("llm: %s is not an asymmetric K-quant on groups of 32", q)
	}
	// **Four bits, because a tile is nibbles.** L8c-3's mixed plan puts the
	// attention layer and the hyper-connection block at `q5_k` for +2.70%
	// against the uniform plan's +4.24%, and a fifth bit is a plane of its
	// own the way ggml's `qh` is — a third stream through the unpack, and a
	// format whose tiles are no longer one byte per two elements. The
	// uniform plan is what this bank is built for; the fifth bit is the
	// decision the mixed one costs.
	if q.Bits != 4 {
		return fmt.Errorf("llm: %s is %d bits and a tile of this bank is nibbles", q, q.Bits)
	}
	if qw != nil && len(qw) != k {
		return fmt.Errorf("llm: %d importance columns for a row of %d", len(qw), k)
	}
	const tile = coopMatTile
	kt := k / tile
	if len(dstQ) != dstN*k/2 {
		return fmt.Errorf("llm: q4_k tile plane is %d bytes, want %d", len(dstQ), dstN*k/2)
	}
	if len(dstR) != (dstN/tile)*nsb*tile*recBytes {
		return fmt.Errorf("llm: q4_k record plane is %d bytes, want %d",
			len(dstR), (dstN/tile)*nsb*tile*recBytes)
	}
	if n > dstN {
		return fmt.Errorf("llm: %d source rows into a %d-row plane", n, dstN)
	}
	if len(src) < n*k {
		return fmt.Errorf("llm: %d source values for %d rows of %d", len(src), n, k)
	}
	var perr error
	var perrOnce sync.Once
	parallelFor((n+packChunk-1)/packChunk, func(ch int) {
		e := newAsymEnc(q, sub)
		for i := ch * packChunk; i < minInt((ch+1)*packChunk, n); i++ {
			r := row(i)
			// The tiles of one n-tile are contiguous across kt, and a tile is
			// 128 bytes, so this row's nibbles start at the n-tile's base and
			// are indexed by (kt, n%16, k%16) from there.
			base := (r / tile) * kt * (tile * tile / 2)
			lane := (r % tile) * (tile / 2)
			rbase := ((r/tile)*nsb*tile + r%tile) * recBytes
			x := src[i*k : (i+1)*k]
			for s := 0; s < nsb; s++ {
				blk := x[s*sub*32 : (s+1)*sub*32]
				var cols []float32
				if qw != nil {
					cols = qw[s*sub*32 : (s+1)*sub*32]
				}
				e.Encode(blk, cols)
				if err := packQ4KRecord(dstR[rbase+s*tile*recBytes:], e); err != nil {
					perrOnce.Do(func() { perr = err })
					return
				}
				for j := 0; j < sub*32; j += 2 {
					c := s*sub*32 + j
					dstQ[base+(c/tile)*(tile*tile/2)+lane+(c%tile)/2] =
						e.Q[j] | e.Q[j+1]<<4
				}
			}
		}
	})
	return perr
}

// q4kDequant reads one element back out of a staged bank exactly as the
// kernels do — the record's pair, `get_scale_min_k4`, and d*sc*l - dmin*m in
// f32. It is what the tests compare against the simulation.
func q4kDequant(bankQ, bankR []byte, n, k, dstRow, col int) float32 {
	const tile = coopMatTile
	kt := k / tile
	sub, nsb, recBytes, err := q4kShape(k)
	if err != nil {
		panic(err)
	}
	base := (dstRow/tile)*kt*(tile*tile/2) + (dstRow%tile)*(tile/2)
	b := bankQ[base+(col/tile)*(tile*tile/2)+(col%tile)/2]
	l := int(b & 0xF)
	if col%2 == 1 {
		l = int(b >> 4)
	}
	sb := col / (sub * 32)
	rec := bankR[((dstRow/tile)*nsb*tile+sb*tile+dstRow%tile)*recBytes:]
	d, dmin, sc, mn := unpackQ4KRecord(rec, sub, (col%(sub*32))/32)
	return d*float32(sc)*float32(l) - dmin*float32(mn)
}

// bankImatrix is one tensor's importance row and the format to encode it
// with: the plan's, or round-to-nearest where the published matrix has no
// entry for the tensor.
//
// The fallback is ggml's own — `quantize_row_q4_K_impl` returns
// `quantize_row_q4_K_ref` on a null `quant_weights`, not the *search* with
// unit weights, which is a third arm and one L8c-3 measured as worse than
// either — and it is what `sim.go`'s `ApplyTo` does. A bank that did anything
// else at an uncovered tensor would not be the format the simulation
// measured, which is the one property this whole stage rests on.
func bankImatrix(name string, q QuantSim) (QuantSim, []float32, error) {
	qw, err := imatrixCols(name, q.Mode)
	if err != nil {
		return q, nil, err
	}
	if qw == nil && (q.Mode == "imatrix" || q.Mode == "imatrix+gain") {
		q.Mode = "rtn"
	}
	return q, qw, nil
}

