446	// NBlocks is the indexer's block count: the cache's cell count over the
447	// compress ratio, which at 7 tokens in a 256-cell cache is 64 — one real block
448	// and 63 that do not exist.
449	func (g *AttnGPU) NBlocks() int { return (g.nKV + g.cfg.Ratio - 1) / g.cfg.Ratio }
