451	// NewAttnGPU stages layers onto the device and builds every pipeline.
452	//
453	// maxTokens is the longest prompt the arenas are built for and nKV the cache's
454	// cell count, which is the reference's padded number rather than the prompt's:
455	// the indexer's block grid, its bias and the rotary table are all cut against
456	// it (research/l2e-attention.md).
457	func NewAttnGPU(dev *vk.Device, cfg AttnConfig, maxTokens, nKV int, layers []AttnWeights, q8 bool) (*AttnGPU, error) {
458		return NewAttnGPUBank(dev, cfg, maxTokens, nKV, layers, bankOf(q8), QuantSim{}, false)
459	}
