461	// NewAttnGPUBank is the same with the bank named rather than implied, the
462	// format the 4.5-bit one encodes with, and whether the indexer's two BF16
463	// projections join it or stay in the fp16 tail (L8c-7).
464	func NewAttnGPUBank(dev *vk.Device, cfg AttnConfig, maxTokens, nKV int, layers []AttnWeights,
465		bank DenseBank, sim QuantSim, idxQuant bool) (*AttnGPU, error) {
466		if maxTokens <= 0 || nKV < maxTokens {
467			return nil, fmt.Errorf("llm: %d tokens in a %d-cell cache", maxTokens, nKV)
468		}
469		if len(layers) == 0 {
470			return nil, fmt.Errorf("llm: no attention layers to stage")
471		}
472		if cfg.HeadDim != 256 {
473			return nil, fmt.Errorf("llm: the attention kernel is built for headDim 256, this checkpoint says %d", cfg.HeadDim)
474		}
475		if cfg.IdxDim != 128 || cfg.IdxHeads != 4 {
476			return nil, fmt.Errorf("llm: the indexer kernels are built for 4 heads of 128, this checkpoint says %d of %d",
477				cfg.IdxHeads, cfg.IdxDim)
478		}
479		if cfg.Ratio <= 0 {
480			return nil, fmt.Errorf("llm: layer has compress ratio %d, so it is not a full-attention layer", cfg.Ratio)
481		}
482		if cfg.NHead%cfg.NHeadKV != 0 {
483			return nil, fmt.Errorf("llm: %d query heads do not group over %d kv heads", cfg.NHead, cfg.NHeadKV)
484		}
485		ok, err := canWMMA(dev)
486		if err != nil {
487			return nil, err
488		}
489		if !ok {
490			return nil, fmt.Errorf("llm: this device has no 16x16x16 fp16 cooperative matrix")
491		}
492		if bank == BankQ4K && sim.Off() {
493			return nil, fmt.Errorf("llm: a q4_k attention bank needs a format to quantise to")
494		}
495		if idxQuant && bank != BankQ4K {
496			// The indexer is BF16 in the checkpoint, so the int8 bank would be a
497			// real re-quantisation of it and L8a declined to make one; only the
498			// 4.5-bit bank has a measured answer to put there.
499			return nil, fmt.Errorf("llm: the indexer's projections are only staged on a q4_k bank, not on %s", bank)
500		}
501		g := &AttnGPU{
502			dev: dev, cfg: cfg, bank: bank, sim: sim, idxQuant: idxQuant,
503			pipes:    make(map[string]*vk.ComputePipeline),
504			tokens:   maxTokens,
505			rows:     maxTokens,
506			nKV:      nKV,
507			lda:      cfg.NEmbd + gemmPad,
508			ldCtx:    cfg.GateWidth() + gemmPad,
509			attn:     DefaultAttnKernel(),
510			gemm:     GEMMKernelFor(maxTokens),
511			outGemm:  OutGEMMKernelFor(maxTokens),
512			autoPlan: true,
513		}
514		// The plane is padded up to the widest tile any rung covers, because the
515		// attention kernel reads whole key blocks and the pack writes whole token
516		// tiles; both would otherwise read whatever a previous, longer run left.
517		align := coopMatTile
518		for _, v := range attnVariants {
519			align = maxInt(align, maxInt(v.rows, v.keys))
520		}
521		for _, v := range gemmBuildsFor(bank) {
522			align = maxInt(align, v.bm)
523		}
524		g.arenaRows = roundUpInt(maxTokens, align)
525		// The selection is the identity wherever it asks for at least as many
526		// cells as the cache holds, so below that it is not run and the attention
527		// kernel takes its dense arm. That is a fact about the cache rather than
528		// about the prompt, and the cache is fixed here.
529		g.sparse = cfg.TopK > 0 && g.selWidth() < nKV
530	
531		if err := g.alloc(len(layers)); err != nil {
532			g.Destroy()
533			return nil, err
534		}
535		if err := g.build(); err != nil {
536			g.Destroy()
537			return nil, err
538		}
539		if err := g.stage(layers); err != nil {
540			g.Destroy()
541			return nil, err
542		}
543		return g, nil
544	}
