546	// alloc lays out the four arenas. Nothing is read here — every size follows
547	// from the config — so the layout can be checked before a weight is touched.
548	func (g *AttnGPU) alloc(nLayers int) error {
549		c := g.cfg
550		rows := g.arenaRows
551		rotHalf := c.RopeDims / 2
552	
553		// fp32 weights: four gammas a layer, then one rotary table for all of them.
554		perLayer := 2*c.HeadDim + 2*c.IdxDim
555		g.wElems = nLayers*perLayer + 2*g.nKV*rotHalf
556		g.wRope = uint32(nLayers * perLayer)
557		var err error
558		if g.wbuf, err = g.dev.NewBuffer(g.wElems * 4); err != nil {
559			return fmt.Errorf("llm: attention fp32 weight arena: %w", err)
560		}
561	
562		alloc := func(n int) uint32 {
563			off := uint32(g.actElems)
564			g.actElems += (n + 63) &^ 63
565			return off
566		}
567		// The sequence position, and it must be the arena's dword 0: the shaders
568		// read it as `actu[0]` (SEQ_PAST in llm_common.glsl), because P1c moved it
569		// out of the push block so that a decode step's command buffer is
570		// byte-identical every token. SetPast writes it.
571		if seq := alloc(1); seq != 0 {
572			return fmt.Errorf("llm: the sequence slot is at %d, and SEQ_PAST is actu[0]", seq)
573		}
574		g.aQKV = alloc(rows * g.qkvN())
575		g.aScore = alloc(rows * g.NBlocks())
576		g.aCell = alloc(rows * g.nKV)
577		// The output gets its own arena rather than being written back over the
578		// projection's. It is 5 MB at 512 tokens against the 27 the fused
579		// projection holds, and aliasing them would cost the layer's own inputs —
580		// which at L6 the residual add still wants — to save that.
581		g.aOut = alloc(rows * c.NEmbd)
582		// The bitmask is allocated for every arena row, not just the prompt's,
583		// because the attention kernel's pad rows index it — they read it as dense
584		// rather than branching, and an unallocated row would be a read past the
585		// buffer.
586		g.aSel = alloc(rows * g.selWords())
587		// The decode GEMV's partial sums, f32 [KSLABS][gemmN] (L8e-1). The wider
588		// of the two projections is the fused one, so 40 x 13952 x 4 = 2.2 MB —
589		// allocated whichever rung runs, because the arena plan is fixed at
590		// construction and the rung is not.
591		g.aPart = alloc(gemvMaxSlabs * g.qkvN())
592		if g.abuf, err = newArena(g.dev, g.actElems*4); err != nil {
593			return fmt.Errorf("llm: attention fp32 activation arena (%d MB): %w", (g.actElems*4)>>20, err)
594		}
595		g.writeSeq()
596	
597		halloc := func(n int) uint32 {
598			off := uint32(g.hElems)
599			g.hElems += (n + 63) &^ 63
600			return off
601		}
602		plane := rows * c.HeadDim
603		g.hXn = halloc(rows * g.lda)
604		g.hQ = halloc(c.NHead * plane)
605		g.hCtx = halloc(rows * g.ldCtx)
606		g.hIdxQ = halloc(rows * c.IdxHeads * c.IdxDim)
607	
608		// The cache, one plane a layer. A query plane is padded token *rows* of
609		// one batch; a key plane is the layer's nKV *cells* and outlives it, so
610		// the two geometries part company here and the shaders are told both.
611		//
612		// It is 2.31 KB a cell a layer — 1 KB of key, 1 KB of value, 256 B of the
613		// indexer's raw key and 64 B of its pooled block — so twelve layers are
614		// 27.7 KB a cell: 57 MB at 2048 cells, 906 MB at 32768. The one structural
615		// limit is that it shares a buffer with the arenas above and
616		// `maxStorageBufferRange` is 4 GiB - 4, which caps this at about 148k
617		// cells; past that the cache wants L6a's array-of-buffers, one a layer.
618		g.kvStride = c.NHeadKV * g.nKV * c.HeadDim
619		g.idxRawStride = g.nKV * c.IdxDim
620		g.idxKStride = g.NBlocks() * c.IdxDim
621		g.hK = halloc(nLayers * g.kvStride)
622		g.hV = halloc(nLayers * g.kvStride)
623		g.hIdxRaw = halloc(nLayers * g.idxRawStride)
624		g.hIdxK = halloc(nLayers * g.idxKStride)
625		if g.hbuf, err = newArena(g.dev, g.hElems*2); err != nil {
626			return fmt.Errorf("llm: attention fp16 activation arena (%d MB): %w", (g.hElems*2)>>20, err)
627		}
628		// Zeroed once: every A operand's pad columns and every short run's pad
629		// rows come from here, and none of these kernels bounds-check.
630		g.hbuf.Zero()
631		g.abuf.Zero()
632	
633		// A layer's two matrices, and on a quantised bank the fp16 tail between
634		// them. An offset into a quantised bank is a **byte**; the tail is
635		// halves, because the build that reads it is the fp16 one.
636		qkvBank, outBank, tailBank := g.qkvN()*c.NEmbd*2, c.NEmbd*c.GateWidth()*2, 0
637		unit := 2
638		if g.quant() {
639			if g.qkvQuantRows()%attnBN != 0 {
640				return fmt.Errorf("llm: the tail starts at column %d, not a whole %d-column block", g.qkvQuantRows(), attnBN)
641			}
642			// Both quantised banks hold **all** qkvN rows of the fused
643			// projection, tail included, because the kernel derives the second
644			// plane's base from gemmN * gemmK and gemmN is the stride of the
645			// output it writes (stage). At 4.5 bits the indexer's 640 unread
646			// rows are 0.82 MB a layer of nibbles nothing reads, against the
647			// 25.7 a layer the width saves.
648			if g.bank == BankQ4K {
649				if err := q4kFits(g.qkvN(), c.NEmbd); err != nil {
650					return err
651				}
652				if err := q4kFits(c.NEmbd, c.GateWidth()); err != nil {
653					return err
654				}
655				qkvBank, outBank = q8Align(q4kBytes(g.qkvN(), c.NEmbd)), q8Align(q4kBytes(c.NEmbd, c.GateWidth()))
656			} else {
657				qkvBank, outBank = q8Align(q8Bytes(g.qkvN(), c.NEmbd)), q8Align(q8Bytes(c.NEmbd, c.GateWidth()))
658			}
659			tailBank = g.qkvTailRows() * c.NEmbd * 2
660			unit = 1
661		}
662		perBank := qkvBank + tailBank + outBank
663		if g.wbank, err = g.dev.NewBuffer(nLayers * perBank); err != nil {
664			return fmt.Errorf("llm: attention weight bank (%d MB): %w", (nLayers*perBank)>>20, err)
665		}
666		g.layers = make([]attnLayerWeights, nLayers)
667		for i := range g.layers {
668			base := uint32(i * perLayer)
669			g.layers[i] = attnLayerWeights{
670				qkv:     uint32(i * perBank / unit),
671				qkvTail: uint32((i*perBank + qkvBank) / 2),
672				out:     uint32((i*perBank + qkvBank + tailBank) / unit),
673				gQ:      base,
674				gK:      base + uint32(c.HeadDim),
675				gIQ:     base + uint32(2*c.HeadDim),
676				gIK:     base + uint32(2*c.HeadDim+c.IdxDim),
677			}
678		}
679		return nil
680	}
