682	func (g *AttnGPU) build() error {
683		bufs := []*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.wbank, g.abuf}
684		pcSize := uint32(unsafe.Sizeof(push{}))
685		for name, spirv := range map[string][]byte{
686			"pack":  shaders.LLMAttnPack,
687			"idx":   shaders.LLMAttnIdx,
688			"score": shaders.LLMAttnScore,
689		} {
690			if err := g.pipeline(name, spirv, vk.PipelineSpec{Buffers: bufs, PushConstantSize: pcSize}); err != nil {
691				return err
692			}
693		}
694		feat := g.dev.Features()
695		sgs, err := g.dev.Physical().SubgroupSizeControl()
696		if err != nil {
697			return fmt.Errorf("llm: subgroup size control: %w", err)
698		}
699		if !feat.SubgroupSizeControl || !sgs.Supported || sgs.MaxSubgroupSize < 64 {
700			return fmt.Errorf("llm: the attention and GEMM rungs need a pinned 64-wide subgroup")
701		}
702		// The selection's bucket search is a subgroup suffix sum over 256 radix
703		// buckets held four waves wide, so it wants the wave pinned for the same
704		// reason the matrix-core rungs do.
705		if err := g.pipeline("select", shaders.LLMAttnSelect, vk.PipelineSpec{
706			Buffers: bufs, PushConstantSize: pcSize, RequiredSubgroupSize: 64,
707		}); err != nil {
708			return err
709		}
710		for _, v := range attnVariants {
711			if err := g.pipeline(string(v.name), v.spirv, vk.PipelineSpec{
712				Buffers: bufs, PushConstantSize: pcSize, RequiredSubgroupSize: 64,
713			}); err != nil {
714				return err
715			}
716		}
717		// Both builds when the bank is quantised: the two projections read the
718		// narrow plane and the indexer's fp16 tail reads halves out of the same
719		// buffer, so the block needs a pipeline of each. On the fp16 bank there
720		// is no tail and the second set is never built.
721		for _, v := range gemmVariants {
722			if err := g.pipeline(string(v.name), v.spirv, vk.PipelineSpec{
723				Buffers: bufs, PushConstantSize: pcSize, RequiredSubgroupSize: 64,
724			}); err != nil {
725				return err
726			}
727		}
728		// Only the two projections read the bank, and only their quantised build
729		// names the sixth buffer; the pack, the indexer, the score and the
730		// attention kernel are unchanged.
731		gemmBufs := bufs
732		if g.quant() {
733			gemmBufs = append(append([]*vk.Buffer{}, bufs...), g.wbank)
734			for _, v := range gemmBuildsFor(g.bank) {
735				if err := g.pipeline(bankPipe(g.bank, v.name), v.spirv, vk.PipelineSpec{
736					Buffers: gemmBufs, PushConstantSize: pcSize, RequiredSubgroupSize: 64,
737				}); err != nil {
738					return err
739				}
740			}
741		}
742		// The decode GEMV, every rung of both banks plus the reduce (L8e-1). They
743		// are built whatever the bank is, because the reduce reads neither and
744		// the fp16 partials arm is what a block on the fp16 bank runs.
745		for name, spirv := range gemvSPIRV {
746			if err := g.pipeline(name, spirv, vk.PipelineSpec{
747				Buffers: gemmBufs, PushConstantSize: pcSize, RequiredSubgroupSize: attnWave,
748			}); err != nil {
749				return err
750			}
751		}
752		return nil
753	}
754	
755	func (g *AttnGPU) pipeline(name string, spirv []byte, spec vk.PipelineSpec) error {
756		mod, err := g.dev.NewShaderModule(spirv)
757		if err != nil {
758			return fmt.Errorf("llm: shader attn.%s: %w", name, err)
759		}
760		g.mods = append(g.mods, mod)
761		pipe, err := g.dev.NewPipeline(mod, spec)
762		if err != nil {
763			return fmt.Errorf("llm: pipeline attn.%s: %w", name, err)
764		}
765		g.pipes[name] = pipe
766		return nil
767	}
768	
769	// stage packs each layer's weights and builds the rotary table.
770	//
771	// The fused projection is the six matrices laid end to end as output rows of
772	// one [qkvN, nEmbd] matrix, in the order the shaders derive: query and gate
773	// interleaved per head (which is the checkpoint's own order), then key, value,
774	// indexer query, indexer key. The pad rows the column block adds are left
775	// zero, and their outputs are never read.
776	func (g *AttnGPU) stage(layers []AttnWeights) error {
777		c := g.cfg
778		for i, w := range layers {
779			for _, t := range []struct {
780				name string
781				off  uint32
782				src  []float32
783				want int
784			}{
785				{"attn_q_norm", g.layers[i].gQ, w.QNorm, c.HeadDim},
786				{"attn_k_norm", g.layers[i].gK, w.KNorm, c.HeadDim},
787				{"indexer.q_norm", g.layers[i].gIQ, w.IdxQNorm, c.IdxDim},
788				{"indexer.k_norm", g.layers[i].gIK, w.IdxKNorm, c.IdxDim},
789			} {
790				if len(t.src) != t.want {
791					return fmt.Errorf("llm: layer %d %s is %d values, want %d", i, t.name, len(t.src), t.want)
792				}
793				g.wbuf.WriteFloat32At(int(t.off), t.src)
794			}
795	
796			for _, t := range []struct {
797				name string
798				src  []float32
799				n    int
800			}{
801				{"attn_q", w.Q, c.QWidth()},
802				{"attn_k", w.K, c.KVWidth()},
803				{"attn_v", w.V, c.KVWidth()},
804				{"indexer.q_proj", w.IdxQ, c.IdxHeads * c.IdxDim},
805				{"indexer.k_proj", w.IdxK, c.IdxDim},
806			} {
807				if len(t.src) != t.n*c.NEmbd {
808					return fmt.Errorf("llm: layer %d %s is %d values, want %d", i, t.name, len(t.src), t.n*c.NEmbd)
809				}
810			}
811			if len(w.O) != c.NEmbd*c.GateWidth() {
812				return fmt.Errorf("llm: layer %d attn_output is %d values, want %d", i, len(w.O), c.NEmbd*c.GateWidth())
813			}
814	
815			base, baseV := g.colK(), g.colV()
816			baseIQ, baseIK := g.colIQ(), g.colIK()
817			if g.bank == BankQ4K {
818				if err := g.stageQ4K(i, w); err != nil {
819					return err
820				}
821				continue
822			}
823			if g.quant() {
824				qrows := g.qkvQuantRows()
825				qs := make([]byte, g.qkvN()*c.NEmbd)
826				sc := make([]uint16, g.qkvN()*c.NEmbd/q8Group)
827				tileBQ8(qs, sc, w.Q, c.QWidth(), c.NEmbd, func(r int) int { return r })
828				tileBQ8(qs, sc, w.K, c.KVWidth(), c.NEmbd, func(r int) int { return base + r })
829				tileBQ8(qs, sc, w.V, c.KVWidth(), c.NEmbd, func(r int) int { return baseV + r })
830				g.wbank.WriteBytesAt(int(g.layers[i].qkv), qs)
831				g.wbank.WriteUint16At((int(g.layers[i].qkv)+len(qs))/2, sc)
832	
833				tail := make([]uint16, g.qkvTailRows()*c.NEmbd)
834				tileB(tail, w.IdxQ, c.IdxHeads*c.IdxDim, c.NEmbd, func(r int) int { return baseIQ - qrows + r })
835				tileB(tail, w.IdxK, c.IdxDim, c.NEmbd, func(r int) int { return baseIK - qrows + r })
836				g.wbank.WriteUint16At(int(g.layers[i].qkvTail), tail)
837	
838				oq := make([]byte, c.NEmbd*c.GateWidth())
839				os := make([]uint16, c.NEmbd*c.GateWidth()/q8Group)
840				tileBQ8(oq, os, w.O, c.NEmbd, c.GateWidth(), func(r int) int { return r })
841				g.wbank.WriteBytesAt(int(g.layers[i].out), oq)
842				g.wbank.WriteUint16At((int(g.layers[i].out)+len(oq))/2, os)
843				continue
844			}
845	
846			qkv := make([]uint16, g.qkvN()*c.NEmbd)
847			tileB(qkv, w.Q, c.QWidth(), c.NEmbd, func(r int) int { return r })
848			tileB(qkv, w.K, c.KVWidth(), c.NEmbd, func(r int) int { return base + r })
849			tileB(qkv, w.V, c.KVWidth(), c.NEmbd, func(r int) int { return baseV + r })
850			tileB(qkv, w.IdxQ, c.IdxHeads*c.IdxDim, c.NEmbd, func(r int) int { return baseIQ + r })
851			tileB(qkv, w.IdxK, c.IdxDim, c.NEmbd, func(r int) int { return baseIK + r })
852			g.wbank.WriteUint16At(int(g.layers[i].qkv), qkv)
853	
854			out := make([]uint16, c.NEmbd*c.GateWidth())
855			tileB(out, w.O, c.NEmbd, c.GateWidth(), func(r int) int { return r })
856			g.wbank.WriteUint16At(int(g.layers[i].out), out)
857		}
858		g.wbuf.WriteFloat32At(int(g.wRope), ropeTable(g.cfg, g.nKV))
859		return nil
860	}
861	
862	// stageQ4K packs one layer onto L8c-4's 4.5-bit bank: LLM.md L8c-7.
863	//
864	// **Each source of the fused matrix is quantised under its own name**, for
865	// the reason L8c-5 gives — the published imatrix has a row per tensor, and
866	// `attn_q`, `attn_k` and `attn_v` are three of them, so a bank that
867	// calibrated the fused thing with one row would not be the format the
868	// simulation measured. `attn_q` is the query *and its gate* interleaved per
869	// head, which is the checkpoint's own tensor and its own imatrix row.
870	//
871	// The indexer's two BF16 projections go in beside them or stay as halves in
872	// the tail, and that is the `qsa_indexer` family (qkvQuantRows). Where they
873	// stay, the quantised plane still covers their rows — the kernel derives the
874	// record plane's base from gemmN * gemmK — so they are written twice and read
875	// once, which costs 0.82 MB a layer and keeps the address arithmetic one
876	// expression.
877	func (g *AttnGPU) stageQ4K(i int, w AttnWeights) error {
878		c := g.cfg
879		q4 := make([]byte, g.qkvN()*c.NEmbd/2)
880		rec := make([]byte, q4kRecPlane(g.qkvN(), c.NEmbd))
881		type source struct {
882			name string
883			src  []float32
884			n    int
885			base int
886		}
887		srcs := []source{
888			{"attn_q.weight", w.Q, c.QWidth(), 0},
889			{"attn_k.weight", w.K, c.KVWidth(), g.colK()},
890			{"attn_v.weight", w.V, c.KVWidth(), g.colV()},
891		}
892		if g.idxQuant {
893			srcs = append(srcs,
894				source{"indexer.q_proj.weight", w.IdxQ, c.IdxHeads * c.IdxDim, g.colIQ()},
895				source{"indexer.k_proj.weight", w.IdxK, c.IdxDim, g.colIK()})
896		}
897		for _, t := range srcs {
898			name := fmt.Sprintf("blk.%d.%s", w.Layer, t.name)
899			q, qw, err := bankImatrix(name, g.sim)
900			if err != nil {
901				return err
902			}
903			base := t.base
904			if err := tileBQ4K(q4, rec, t.src, t.n, c.NEmbd,
905				func(r int) int { return base + r }, q, qw); err != nil {
906				return fmt.Errorf("llm: layer %d %s: %w", i, name, err)
907			}
908		}
909		g.wbank.WriteBytesAt(int(g.layers[i].qkv), q4)
910		g.wbank.WriteBytesAt(int(g.layers[i].qkv)+len(q4), rec)
911	
912		if rows := g.qkvTailRows(); rows > 0 {
913			qrows := g.qkvQuantRows()
914			tail := make([]uint16, rows*c.NEmbd)
915			tileB(tail, w.IdxQ, c.IdxHeads*c.IdxDim, c.NEmbd, func(r int) int { return g.colIQ() - qrows + r })
916			tileB(tail, w.IdxK, c.IdxDim, c.NEmbd, func(r int) int { return g.colIK() - qrows + r })
917			g.wbank.WriteUint16At(int(g.layers[i].qkvTail), tail)
918		}
919	
920		name := fmt.Sprintf("blk.%d.attn_output.weight", w.Layer)
921		q, qw, err := bankImatrix(name, g.sim)
922		if err != nil {
923			return err
924		}
925		oq := make([]byte, c.NEmbd*c.GateWidth()/2)
926		orec := make([]byte, q4kRecPlane(c.NEmbd, c.GateWidth()))
927		if err := tileBQ4K(oq, orec, w.O, c.NEmbd, c.GateWidth(),
928			func(r int) int { return r }, q, qw); err != nil {
929			return fmt.Errorf("llm: layer %d %s: %w", i, name, err)
930		}
931		g.wbank.WriteBytesAt(int(g.layers[i].out), oq)
932		g.wbank.WriteBytesAt(int(g.layers[i].out)+len(oq), orec)
933		return nil
934	}
935	
936	// ropeTable is the rotary's cosines for every cache position followed by its
937	// sines: [nKV][rot/2] then [nKV][rot/2].
938	//
939	// The angles are built here, in float64, rather than from a `pow` per lane,
940	// for the reason the shader's header gives — the CPU reference walks
941	// `theta *= base^(-2/rot)` in float64 and a float32 `pow` does not reproduce
942	// it, which at a long context is an absolute angle error and not a relative
943	// one. Position is the only input, so one table serves the query, the key and
944	// the indexer's pooled blocks, whose position is the first cell they cover.
945	//
946	// It is the interleaved M-RoPE's angle and not plain NeoX's as a matter of
947	// derivation rather than of coincidence: this calls the same RoPEMulti the CPU
948	// reference does, on a basis vector, and reads the rotation back off it. On a
949	// text batch the two agree bit for bit (`TestRoPEMultiIsNeoXOnText`), and the

