// rows, and `pc.gateOff` here is not a weight at all but the validation arena
// the collapse optionally writes the wide gate into — so the tail branch is
// compiled out rather than guarded, which is what keeps the k-loop to one
// `coopMatLoad` of B (L8a-3).
shared float gateLDS[TILE * BN];
#else
// MODE 0 and MODE 2 both read the fp16 A operand at xnOff: the hyper-
// connection block's normalised residual, and the PLE block's gathered
// embedding.
#define A_BUF_OFF pc.xnOff
#define A_LDA pc.lda
#define Q8_TAIL 1
#if MODE == 0
// The column block holding the first non-Q8 row, not the row itself: see the
// note at the branch.
#define Q8_SPLIT ((pc.lowRank / BN) * BN)
#else
#define Q8_SPLIT pc.lowRank
#endif
#endif

float sigmoidf(float x) { return 1.0 / (1.0 + exp(-x)); }

void main() {
    uint wn0 = gl_WorkGroupID.x * BN;
    uint wm0 = gl_WorkGroupID.y * BM;

    ACC_T acc[WM][WN];
    [[unroll]] for (uint i = 0u; i < WM; i++) {
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            acc[i][j] = ACC_T(0.0);
        }
    }

    uint ktiles = pc.gemmK / TILE;
#ifdef Q4B
    // The nibble tiles are at pc.bOff and the record plane follows them, so
    // its base is derivable and needs no push field of its own — the same
    // arrangement, and the same reason, as the Q8 arm below.
    uint qw0 = pc.bOff >> 2;                                   // the tiles, in words
    uint rec0 = (pc.bOff + ((pc.gemmN * pc.gemmK) >> 1)) >> 2; // the records, in words
    uint nsb = pc.gemmK / Q4K_SB;                              // super-blocks a row
    uint lane = gl_LocalInvocationID.x;
    uint nt0 = wn0 / TILE;
    // This lane's column of the slab, and the record it holds for it. Lanes
    // at or past BN have no column; BN is 48 or 64 against a 64-wide wave.
    // The pair is one word and the packed pairs are the rest, which is three
    // words at eight groups and four at ten.
    uint myRecD = 0u;
    uvec4 myRecS = uvec4(0u);
    uint myNT = nt0 + (lane >> 4), myRow = lane & 15u;
#endif
#ifdef Q8B
    // The tiles are bytes at pc.bOff and the scale plane is the halves that
    // follow them, so its base is derivable and needs no field of its own —
    // which matters, because 64 uints is this device's whole push range and
    // the block has been full since L5b. A matrix is staged as exactly
    // gemmN x gemmK bytes.
    uint qw0 = pc.bOff >> 2;                       // the tiles, in words
    uint sc0 = (pc.bOff + pc.gemmN * pc.gemmK) >> 1;  // the plane, in halves
    uint kgroups = pc.gemmK >> 5;
    uint lane = gl_LocalInvocationID.x;
    uint nt0 = wn0 / TILE;
#endif
#ifdef QBANK
#ifdef Q8_TAIL
    // **Not every row of a fused matrix is Q8_0 in the checkpoint**, and the
    // ones that are not stay halves rather than being re-quantised: the
    // gated DeltaNet's F32 alpha and beta, the attention layer's BF16 indexer
    // projections, the hyper-connection block's F32 inject. They are the
    // *last* rows of their matrix in every case, so the split is one number
    // and the tail is a fp16 fragment-tiled matrix of its own at
    // `pc.gateOff`, numbered from the split. A whole column block falls on
    // one side or the other, so the branch below is per workgroup and not per
    // tile.
    //
    // **Where the split falls is the one thing MODE 0 does differently**, and
    // it is L8b's whole difficulty. In MODE 2 the tail begins at
    // `pc.lowRank`, which is a whole BN block by construction because the
    // host chose the fused row order. In MODE 0 it cannot be: `inject` is
    // four F32 rows at lowRank = 320 of a fused N of 336, and BN is 48
    // because 336 is 21 tiles and 21 is 3 x 7. So the split is the *column
    // block that contains* the first non-Q8 row — `pc.lowRank` rounded down
    // to BN, 288 here — and the 32 low-rank rows between it and inject are
    // staged in both planes, read out of the fp16 one, and cost 0.33 MB a
    // mixer of the 3.2 the block saves.
    uint qSplit = Q8_SPLIT;
    bool tail = pc.gateOff != NO_W && wn0 >= qSplit;
    uint tailNT = nt0 - qSplit / TILE;
#endif
#endif
    // The reduction. On the Q8 arm it is written twice rather than branched
    // inside: the tail's B comes straight out of the fp16 bank as it always
    // did, the rest through LDS, and a compare in the k-loop cost 1.27x on
    // the DeltaNet's output projection — a matrix with no tail at all —
    // because the two `coopMatLoad`s in one loop body are register pressure
    // the ladder is already bound by (L2f-5, L3b-4).
#if defined(QBANK) && defined(Q8_TAIL)
    if (tail) {
        for (uint k0 = 0u; k0 < pc.gemmK; k0 += BK) {
            [[unroll]] for (uint kt = 0u; kt < BK_TILES; kt++) {
                FRAG_A_T fragA[WM];
                FRAG_B_T fragB[WN];
                [[unroll]] for (uint i = 0u; i < WM; i++) {
                    coopMatLoad(fragA[i], hact, A_BUF_OFF + (wm0 + i * TILE) * A_LDA + k0 + kt * TILE,
                        A_LDA, gl_CooperativeMatrixLayoutRowMajor);
                }
                [[unroll]] for (uint j = 0u; j < WN; j++) {
