	}

	t.Logf("read %.2f MB a token against the fp16 bank's %.2f", float64(q4)/1e6, float64(half)/1e6)
	if ratio := float64(half) / float64(q4); ratio < 3.4 || ratio > 3.6 {
		t.Fatalf("a token reads %.3fx less than on halves, want ~3.5", ratio)
