9	// The GPU half of L2e, checked the way L2c and L2d were: against the CPU
10	// reference in attn.go first, because that is what the kernels are a port of,
11	// and against llama.cpp's own tensors behind it, because that is what the CPU
12	// reference was built against.
13	//
14	// Layer 3 is the only full-attention layer in the four the trace covers — the
15	// interval is 4 — and `hc_mixed-3` is llama.cpp's own value for its input, so
16	// every comparison below is that stage's own and not an accumulation.
17	
18	// attnGPU stages layer 3 and runs it over the trace's own input.
19	func attnGPU(t *testing.T) (*AttnGPU, *Trace, AttnConfig, AttnWeights, []float32, int, int, func()) {
20		t.Helper()
21		_, tr, c, w, nTok, nKV := attnFixtures(t)
22		in, err := tr.Get("hc_mixed-3", 0)
23		if err != nil {
24			t.Fatal(err)
