28		if err != nil {
29			done()
30			t.Fatal(err)
31		}
32		t.Logf("staged: %.1f MB of weights, %.1f MB of arenas, %d cells, %d blocks",
33			float64(g.WeightBytes())/1e6, float64(g.ActivationBytes())/1e6, g.NKV(), g.NBlocks())
34		return g, tr, c, w, in.Vals, nTok, nKV, func() { g.Destroy(); done() }
35	}
