37	// TestAttnGPUPushBlockFits is the cheap structural guard. The push block is a
38	// contract with four shaders and vk.DispatchMultiTimed records a sequence into
39	// one command buffer only if every pipeline declares the same range, so the
40	// one number that has to hold is that the whole vertical's block still fits
41	// the device's limit — which the attention group nearly doubled.
42	func TestAttnGPUPushBlockFits(t *testing.T) {
43		size := int(unsafe.Sizeof(push{}))
44		t.Logf("push block: %d uints, %d bytes", size/4, size)
45		if size%4 != 0 {
46			t.Errorf("push block is %d bytes, which is not whole uints", size)
47		}
48		if size > 256 {
49			t.Errorf("push block is %d bytes, past the 256 this device reports", size)
50		}
51	}
52	
53	// TestAttnGPUFusedProjection is the gate on the layout the whole layer rests
54	// on: six of llama.cpp's matrices packed as column ranges of one.
55	//
56	// Nothing downstream can be right if the ranges are wrong, and nothing
57	// downstream says so clearly — a query read at the key's columns is a
58	// perfectly plausible tensor. So each range is compared against the tensor
59	// llama.cpp names, where the trace has one, and against the CPU reference's
60	// own matvec where it does not.
61	func TestAttnGPUFusedProjection(t *testing.T) {
62		g, tr, c, w, in, nTok, _, done := attnGPU(t)
63		defer done()
64	
65		if err := g.Upload(in, nTok); err != nil {
66			t.Fatal(err)
67		}
68		if err := g.Run(0); err != nil {
69			t.Fatal(err)
70		}
71	
72		// The reference, exactly: fp32 activations against fp32 weights, which is
73		// what the kernel computes in fp16 operands with fp32 accumulators.
74		proj := func(weight []float32, n int) []float32 {
75			out := make([]float32, nTok*n)
76			for i := 0; i < nTok; i++ {
77				matvec(out[i*n:(i+1)*n], weight, in[i*c.NEmbd:(i+1)*c.NEmbd], n, c.NEmbd)
78			}
79			return out
80		}
81		for _, tc := range []struct {
82			name  string
83			col   int
84			width int
85			want  []float32
86			tol   float64
87		}{
88			{"attn_q+gate", 0, c.QWidth(), proj(w.Q, c.QWidth()), 2e-3},
89			{"attn_k", g.ColK(), c.KVWidth(), proj(w.K, c.KVWidth()), 2e-3},
90			{"attn_v", g.ColV(), c.KVWidth(), proj(w.V, c.KVWidth()), 2e-3},
91			{"indexer_q_raw", g.ColIQ(), c.IdxHeads * c.IdxDim, proj(w.IdxQ, c.IdxHeads*c.IdxDim), bankTol(2e-3, 5e-3)},
92			{"indexer_k_raw", g.ColIK(), c.IdxDim, proj(w.IdxK, c.IdxDim), bankTol(2e-3, 5e-3)},
93		} {
94			r, err := compare(g.Column(tc.col, tc.width), tc.want)
95			if err != nil {
