101			}
102		}
103	
104		// And the one of the six the trace names directly. It is dumped before the
105		// fp16 cache write, so this is the projection alone.
106		want, err := tr.Get("indexer_k_raw-3", 0)
107		if err != nil {
108			t.Fatal(err)
109		}
110		r, err := compare(g.Column(g.ColIK(), c.IdxDim), want.Vals)
111		if err != nil {
112			t.Fatal(err)
113		}
114		t.Logf("%-14s           vs llama.cpp  %v", "indexer_k_raw", r)
115		if r.rms > bankTol(2e-3, 5e-3) {
116			t.Errorf("indexer_k_raw-3: rms %.3e over %.0e (%v)", r.rms, bankTol(2e-3, 5e-3), r)
117		}
118	}
119	
120	// TestAttnGPUIndexer is the gate on the QSA indexer: the pooled key, the
121	// query, the score and the per-cell expansion, all on the device.
122	//
123	// The pooled key is where the reference's fp16 cache shows, and this path
124	// reproduces it rather than modelling it — the cache is fp16 here because the
125	// arena is, so `float16_t()` on the way out of the projection is the same
126	// arithmetic and not an approximation of it. The tolerances say so: the pooled
127	// key lands where `RefQ8` does on the CPU, not where `Exact` does.
128	func TestAttnGPUIndexer(t *testing.T) {
129		g, tr, c, w, in, nTok, nKV, done := attnGPU(t)
130		defer done()
131	
132		if err := g.Upload(in, nTok); err != nil {
133			t.Fatal(err)
134		}
135		if err := g.Run(0); err != nil {
136			t.Fatal(err)
137		}
138	
139		ref := c
140		ref.Act = RefQ8
141		cpu := AttnLayer(ref, w, in, nTok, nKV)
142	
143		for _, tc := range []struct {
144			name      string
145			got, want []float32
146			tol, rtol float64
147		}{
148			{"indexer_k_pooled-3", g.IdxK(), cpu.IdxK, bankTol(1e-3, 5e-3), bankTol(1e-3, 5e-3)},
149			{"indexer_q-3", g.IdxQ(), cpu.IdxQ, bankTol(1e-3, 5e-3), bankTol(1e-3, 5e-3)},
150			{"indexer_score-3", g.Score(), cpu.IdxScore, 5e-2, 5e-2},
151		} {
152			r, err := compare(tc.got, tc.want)
153			if err != nil {
154				t.Fatalf("%s against the CPU reference: %v", tc.name, err)
155			}
156			t.Logf("%-20s vs CPU RefQ8  %v", tc.name, r)
157			if r.rms > tc.tol {
158				t.Errorf("%s: rms %.3e against the CPU reference, over %.1e (%v)", tc.name, r.rms, tc.tol, r)
159			}
160			// indexer_k_pooled is dumped before the norm and the rotary, so the
161			// device tensor — which carries both — is compared to llama.cpp under
162			// the name of the tensor it actually is.
163			name := tc.name
164			if name == "indexer_k_pooled-3" {
165				name = "indexer_k-3"
166			}
167			want, err := tr.Get(name, 0)
168			if err != nil {
169				t.Fatal(err)
170			}
171			if r, err = compare(tc.got, want.Vals); err != nil {
172				t.Fatalf("%s against llama.cpp: %v", name, err)
173			}
174			t.Logf("%-20s vs llama.cpp  %v", name, r)
175			if r.rms > tc.rtol {
176				t.Errorf("%s: rms %.3e against llama.cpp, over %.1e (%v)", name, r.rms, tc.rtol, r)
177			}
178		}
179	
180		// The per-cell score carries infinities — every masked cell is one — so it
181		// is compared as a mask plus the finite values, not by subtraction. The
182		// mask has to agree exactly: a cell the reference calls invisible and we
183		// do not is a cell attention would read.
184		want, err := tr.Get("indexer_score_tokens-3", 0)
185		if err != nil {
186			t.Fatal(err)
187		}
188		got := g.Cells()
189		if len(got) != len(want.Vals) {
190			t.Fatalf("indexer_score_tokens-3 is %d values, reference has %d", len(got), len(want.Vals))
191		}
192		var finite, worst float64
193		for i := range want.Vals {
194			gv, wv := float64(got[i]), float64(want.Vals[i])
195			if math.IsInf(wv, -1) != math.IsInf(gv, -1) {
196				t.Fatalf("cell %d of token %d: got %g, reference %g — the mask disagrees",
197					i%nKV, i/nKV, gv, wv)
198			}
199			if math.IsInf(wv, -1) {
200				continue
201			}
202			finite++
203			if d := math.Abs(gv - wv); d > worst {
204				worst = d
205			}
206		}
207		t.Logf("indexer_score_tokens-3 %.0f finite cells of %d, worst |diff| %.3e", finite, len(got), worst)
208		if worst > 1e-1 {
209			t.Errorf("indexer_score_tokens-3: worst finite disagreement %.3e", worst)
210		}
211	}
