1	package main
2	
3	// The hyper-connection block's benchmark: LLM.md L2c, against the per-op
4	// attribution of llama.cpp's own graph that L2a produced.
5	//
6	//	go run ./cmd/llm -hc                       # the default ladder, 64..2048
7	//	go run ./cmd/llm -hc -tokens 512 -ladder   # every rung at the reference's ubatch
8	//	go run ./cmd/llm -hc -csv results/l2c_hc.csv
9	//
10	// What is timed is GPU dispatch time, swept across every staged mixer so the
11	// weights are read as cold as the real graph reads them — one mixer is 13.4 MB
12	// and would otherwise sit in the 32 MiB MALL. Wall clock around a run is not a
13	// measurement of the block: it carries the upload and the read-back, and this
14	// arena reads at 0.2 GB/s.
15	
16	import (
17		"encoding/csv"
18		"fmt"
19		"os"
20		"strconv"
21		"strings"
22		"time"
23	
24		"strix-halo-vulkan/llm"
25		"strix-halo-vulkan/vk"
26	)
27	
28	// llamaOp is one line of llama.cpp's prefill graph at `-ub 512`, from
29	// results/l2a_prefill_ops.csv — its best ubatch, so the right baseline to
30	// quote. Totals are per graph of 512 tokens, microseconds.
31	type llamaOp struct {
32		kind       string
33		op         string
34		dispatches int
35		usTotal    float64
36	}
37	
38	// The four lines of that graph that are nameably this block, plus the one
39	// piece of glue whose dispatch count identifies it beyond doubt: REPEAT is
40	// 98 dispatches, which is the mixer count, and it is the combine broadcasting
41	// one scatter weight per stream across 2560 features.
42	//
43	// The rest of the block's glue — the gamma multiply, the gate's sigmoid, the
44	// xn*gate multiply, the collapse's adds, the combine's scale/sigmoid/mul/add
45	// — is inside MUL (479), ADD (231), SIGMOID (326) and MULTI_ADD (170), which
46	// the model's other blocks also use. L2a attributes the whole elementwise
47	// category at 30.6% of the graph; nothing here needs that attribution to be
48	// exact, because every one of those dispatches is *absent* from our graph
49	// rather than faster in it.
50	var llamaHC = []llamaOp{
51		{"norm", "RMS_NORM(2560,4,512,1)", 98, 16707.5},
52		{"down", "MUL_MAT q8_0 m=320 n=512 k=10240", 95, 38055.6},
53		{"down", "MUL_MAT f32 m=4 n=512 k=10240 (inject)", 95, 125231.0},
54		{"up", "MUL_MAT q8_0 m=10240 n=512 k=320", 95, 30726.0},
55		{"combine", "REPEAT", 98, 15928.3},
56	}
57	
58	// llamaGraphUs is that whole graph, summed over every op line at `-ub 512`.
59	const llamaGraphUs = 1164730.0
60	
61	// mixersPerGraph is how many mixers a forward pass runs: two per layer plus
62	// the one at the head. llama.cpp's dispatch counts are 95 and 98 because the
63	// head mixer has no inject and its norm is dumped separately; ours is one
64	// number, and the difference is inside the noise of the comparison.
65	const mixersPerGraph = 97
66	
67	func hcBench(model string, tokens []int, mixers, iters int, ladder bool, csvPath string) error {
68		m, err := llm.Open(model)
69		if err != nil {
70			return err
71		}
72		defer m.Close()
73		cfg := m.Config.HCConfig()
